class Solution:
    def sequentialDigits(self, low: int, high: int) -> list[int]:
        result = []
        for start in range(1, 10):
            num = start
            nxt = start
            while num <= high and nxt < 10:
                if num >= low:
                    result.append(num)
                nxt += 1
                if nxt < 10:
                    num = num * 10 + nxt
        result.sort()
        return result

